WH.Gatherer.addData(6, 11, {"48979":{"name_enus":"Butchery","icon":"inv_axe_68","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Whenever you kill an enemy that grants experience or honor, you generate up to 10 Runic Power.  In addition, you generate 1 Runic Power per 5 sec while in combat."},"49182":{"name_enus":"Blade Barrier","icon":"ability_upgrademoonglaive","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You take 2% less damage from all sources."},"48978":{"name_enus":"Bladed Armor","icon":"inv_shoulder_36","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your attack power by 2 for every 180 armor value you have."},"94553":{"name_enus":"Improved Blood Tap","icon":"spell_deathknight_bloodtap","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown of your Blood Tap ability by 15 sec."},"49004":{"name_enus":"Scent of Blood","icon":"ability_rogue_bloodyeye","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You have a 15% chance after dodging, parrying or taking direct damage to gain the Scent of Blood effect, causing your next melee hit to generate 10 Runic Power."},"81131":{"name_enus":"Scarlet Fever","icon":"ability_rogue_vendetta","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Causes your Blood Plague to afflict enemies with Scarlet Fever, reducing their physical damage dealt by 5% for 21 sec."},"85793":{"name_enus":"Hand of Doom","icon":"ability_deathknight_desolation","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown of your Strangulate ability by 30 sec."},"49219":{"name_enus":"Blood-Caked Blade","icon":"ability_criticalstrike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your autoattacks have a 10% chance to cause a Blood-Caked Strike, which hits for 25% weapon damage plus 12.5% for each of your diseases on the target."},"49222":{"name_enus":"Bone Shield","icon":"ability_deathknight_boneshield","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Surrounds you with a barrier of whirling bones.  The shield begins with 6 charges, and each damaging attack consumes a charge.  While at least 1 charge remains, you take 20% less damage from all sources and deal 2% more damage with all attacks, spells and abilities [<span class='q2'>Glyph of Bone Shield</span>: <span class='q9'>and move up to 0% faster</span>].  Lasts 5 min."},"49042":{"name_enus":"Toughness","icon":"spell_holy_devotion","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your armor value from items by 3%."},"53137":{"name_enus":"Abomination's Might","icon":"ability_warrior_intensifyrage","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases melee attack power by 10% and ranged attack power by 5% of party and raid members within 100 yards.  Also increases your total Strength by 1%."},"81125":{"name_enus":"Sanguine Fortitude","icon":"ability_deathknight_sanguinfortitude","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Icebound Fortitude reduces damage taken by an additional 15%, and costs 50% less Runic Power to activate."},"49027":{"name_enus":"Blood Parasite","icon":"spell_shadow_soulleech","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your melee attacks have a 5% chance to spawn a Bloodworm. The Bloodworm attacks your enemies, gorging itself with blood until it bursts to heal nearby allies.  Lasts up to 20 sec."},"50365":{"name_enus":"Improved Blood Presence","icon":"spell_deathknight_bloodpresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your rune regeneration by 10% and reduces the chance that you will be critically hit by melee attacks while in Blood Presence by 3%.  In addition, while in Frost Presence or Unholy Presence, you retain 2% damage reduction from Blood Presence."},"52284":{"name_enus":"Will of the Necropolis","icon":"ability_creature_cursed_02","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When a damaging attack brings you below 30% of your maximum health, the cooldown on your Rune Tap ability is refreshed and your next Rune Tap has no cost, and all damage taken is reduced by 8% for 8 sec.  This effect cannot occur more than once every 45 seconds."},"48982":{"name_enus":"Rune Tap","icon":"spell_deathknight_runetap","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Converts 1 Blood Rune into 10% of your maximum health.<!--cooldown:48985:20 sec cooldown--><!--cooldown:49488:10 sec cooldown--><!--cooldown:49489:until cancelled-->"},"55233":{"name_enus":"Vampiric Blood","icon":"spell_shadow_lifedrain","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"[<span class='q2'>Glyph of Vampiric Blood</span>: <span class='q9'>Increases the amount of health the Death Knight receives from healing spells and effects by 25% for 10 sec</span> / Temporarily grants the Death Knight 15% of maximum health and increases the amount of health received from healing spells and effects by 25% for 10 sec.  After the effect expires, the health is lost.]"},"62905":{"name_enus":"Improved Death Strike","icon":"spell_deathknight_butcher2","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage done by your Death Strike by 40%, its critical strike chance by 10%, and its amount healed by 15%."},"81135":{"name_enus":"Crimson Scourge","icon":"spell_deathknight_bloodboil","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage dealt by your Blood Boil by 20%, and when you land a melee attack on a target that is infected with your Blood Plague, there is a 5% chance that your next Blood Boil will consume no runes."},"49028":{"name_enus":"Dancing Rune Weapon","icon":"inv_sword_07","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Summons a second rune weapon that fights on its own for 12 sec, mirroring the Death Knight's attacks.  The rune weapon also assists in defense of its master, granting an additional 20% parry chance while active."},"49455":{"name_enus":"Runic Power Mastery","icon":"spell_arcane_arcane01","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your maximum Runic Power by 10."},"55061":{"name_enus":"Icy Reach","icon":"spell_frost_manarecharge","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the range of your Icy Touch,  Chains of Ice and Howling Blast by 5 yards."},"49226":{"name_enus":"Nerves of Cold Steel","icon":"ability_dualwield","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your chance to hit with one-handed melee weapons by 1% and increases the damage done by your off-hand weapon by 8%."},"51468":{"name_enus":"Annihilation","icon":"inv_weapon_hand_18","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage dealt by your Obliterate ability by 15%."},"49039":{"name_enus":"Lichborne","icon":"spell_shadow_raisedead","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Draw upon unholy energy to become undead for 10 sec.  While undead, you are immune to Charm, Fear and Sleep effects."},"51983":{"name_enus":"On a Pale Horse","icon":"ability_mount_undeadhorse","screenshot":{},"displayName":"","skillcategory":0,"rank_enus":"Rank 1","description_enus":"You become as hard to stop as death itself.  The duration of movement-slowing effects used against you is reduced by 15%, and your mounted speed is increased by 10%.  This does not stack with other movement speed increasing effects."},"49137":{"name_enus":"Endless Winter","icon":"spell_shadow_twilight","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"The cost of your Mind Freeze is reduced to 10 Runic Power."},"49024":{"name_enus":"Merciless Combat","icon":"inv_sword_112","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Icy Touch, Howling Blast, Obliterate and Frost Strike do an additional 6% damage when striking targets with less than 35% health."},"49149":{"name_enus":"Chill of the Grave","icon":"spell_frost_frostshock","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Chains of Ice, Howling Blast, Icy Touch and Obliterate generate 5 additional Runic Power."},"51123":{"name_enus":"Killing Machine","icon":"inv_sword_122","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your autoattacks have a chance to grant a 100% critical strike bonus to your next Obliterate or Frost Strike."},"49188":{"name_enus":"Rime","icon":"spell_frost_freezingbreath","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Obliterate has a 15% chance to cause your next Howling Blast or Icy Touch to consume no runes."},"51271":{"name_enus":"Pillar of Frost","icon":"ability_deathknight_pillaroffrost","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Calls upon the power of Frost to increase the Death Knight's Strength by 20%.  Icy crystals hang heavy upon the Death Knight's body, providing immunity against external movement such as knockbacks.  Lasts 20 sec."},"55610":{"name_enus":"Improved Icy Talons","icon":"spell_deathknight_icytalons","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases the melee and ranged attack speed of all party and raid members within 100 yards by 10%, and your own attack speed by an additional 5%."},"81327":{"name_enus":"Brittle Bones","icon":"ability_deathknight_brittlebones","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Strength is increased by 2% and your Frost Fever chills the bones of its victims, increasing their physical damage taken by 2%."},"50040":{"name_enus":"Chilblains","icon":"spell_frost_wisp","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Victims of your Frost Fever disease are Chilled, reducing movement speed by 25% for 10 sec, and your Chains of Ice immobilizes targets for 1.50 sec."},"49203":{"name_enus":"Hungering Cold","icon":"inv_staff_15","screenshot":{"id":100202,"imageType":2},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Purges the earth around the Death Knight of all heat.  Enemies within 10 yards are afflicted with Frost Fever and trapped in ice, preventing them from performing any action for 10 sec.  Enemies are considered Frozen, but any damage other than diseases will break the ice."},"50384":{"name_enus":"Improved Frost Presence","icon":"spell_deathknight_frostpresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your bonus damage while in Frost Presence by an additional 2%.  In addition, while in Blood Presence or Unholy Presence, you retain 2% increased Runic Power generation from Frost Presence."},"65661":{"name_enus":"Threat of Thassarian","icon":"ability_dualwieldspecialization","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When dual-wielding, your Death Strikes, Obliterates, Plague Strikes, Rune Strikes, Blood Strikes and Frost Strikes have a 30% chance to also deal damage with your off-hand weapon. Off-hand strikes from Rune Strike generate increased threat."},"81330":{"name_enus":"Might of the Frozen Wastes","icon":"inv_sword_120","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When wielding a two-handed weapon, your melee attacks deal an additional 3% damage and your autoattacks have a 15% chance to generate 10 Runic Power."},"49184":{"name_enus":"Howling Blast","icon":"spell_frost_arcticwinds","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Blast the target with a frigid wind, dealing [((<!--pts2:1:0:49184-->1322<!----> + <!--pts2:2:0:49184--> 1322<!---->) / 2) + (Attack power * 0.44)] Frost damage to that foe, and [(0.5 * (((<!--pts2:1:0:49184-->1322<!----> + <!--pts2:2:0:49184--> 1322<!---->) / 2) + (Attack power * 0.44)))] Frost damage to all other enemies within 10 yards [<span class='q2'>Glyph of Howling Blast</span>: <span class='q9'>infecting all targets with Frost Fever</span>]."},"49588":{"name_enus":"Unholy Command","icon":"spell_deathknight_strangulate","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown of your Death Grip ability by 5 sec, and gives you a 50% chance to refresh its cooldown when dealing a killing blow to a target that grants experience or honor."},"48962":{"name_enus":"Virulence","icon":"spell_shadow_burningspirit","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage done by your diseases by 10%."},"49036":{"name_enus":"Epidemic","icon":"spell_shadow_shadowwordpain","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the duration of Blood Plague and Frost Fever by 4 sec."},"55666":{"name_enus":"Desecration","icon":"spell_shadow_shadowfiend","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Plague, Scourge, and Necrotic Strikes defile the ground within 7 yards of your target. Enemies in the area are slowed by 25% while standing on the unholy ground. Does not trigger against targets that are immune to movement-slowing effects. Lasts 20 sec."},"81338":{"name_enus":"Resilient Infection","icon":"ability_creature_disease_05","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When your diseases are dispelled by an enemy, you have a 50% chance to activate a Frost Rune if Frost Fever was removed, or an Unholy Rune if Blood Plague was removed."},"48963":{"name_enus":"Morbidity","icon":"spell_shadow_deathanddecay","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage and healing of Death Coil by 5% and Death and Decay by 10%."},"51459":{"name_enus":"Runic Corruption","icon":"spell_shadow_rune","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cost of your Death Coil by 3, and causes your Runic Empowerment ability to no longer refresh a depleted rune, but instead to increase your rune regeneration rate by 50% for 3 sec."},"49016":{"name_enus":"Unholy Frenzy","icon":"spell_shadow_unholyfrenzy","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Incites a friendly party or raid member into a killing frenzy for 30 sec.  The target is Enraged, increasing their melee and ranged haste by 20%, but causes them to lose health equal to 2% of their maximum health every 3 sec."},"91316":{"name_enus":"Contagion","icon":"spell_shadow_plaguecloud","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage of your diseases spread via Pestilence by 50%."},"48965":{"name_enus":"Shadow Infusion","icon":"spell_shadow_requiem","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Grants your successful Death Coils a 33% chance to empower your active Ghoul, increasing its damage dealt by 6% for 30 sec.  Stacks up to 5 times."},"96269":{"name_enus":"Death's Advance","icon":"spell_shadow_demonicempathy","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"While your Unholy Runes are both depleted, movement-impairing effects may not reduce you below 60% of normal movement speed."},"49224":{"name_enus":"Magic Suppression","icon":"spell_shadow_antimagicshell","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the spell damage absorption of your Anti-Magic Shell by an additional 8%, and causes damage absorbed by Anti-Magic Shell to energize the Death Knight with Runic Power."},"51745":{"name_enus":"Rage of Rivendare","icon":"inv_weapon_halberd14","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage of your Plague Strike, Scourge Strike, and Festering Strike abilities by 15%."},"49194":{"name_enus":"Unholy Blight","icon":"spell_shadow_contagion","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Causes the victims of your Death Coil to be surrounded by a vile swarm of unholy insects, taking 10% of the damage done by the Death Coil over 10 sec, and preventing any diseases on the victim from being dispelled."},"51052":{"name_enus":"Anti-Magic Zone","icon":"spell_deathknight_antimagiczone","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Places a large, stationary Anti-Magic Zone that reduces spell damage done to party or raid members inside it by 75%.  The Anti-Magic Zone lasts for 10 sec or until it absorbs (10000 + 2 * Attack power) spell damage."},"50391":{"name_enus":"Improved Unholy Presence","icon":"spell_deathknight_unholypresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Grants you an additional 5% haste while in Unholy Presence.  In addition, while in Blood Presence or Frost Presence, you retain 8% increased movement speed from Unholy Presence."},"63560":{"name_enus":"Dark Transformation","icon":"achievement_boss_festergutrotface","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Consume 5 charges of Shadow Infusion on your Ghoul to transform it into a powerful undead monstrosity for 30 sec.  The Ghoul's abilities are empowered and take on new functions while the transformation is active."},"51099":{"name_enus":"Ebon Plaguebringer","icon":"ability_creature_cursed_03","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Plague Strike, Icy Touch, Chains of Ice, and Outbreak abilities also infect their target with Ebon Plague, which increases damage taken from your diseases by 15% and all magic damage taken by an additional 8%."},"49018":{"name_enus":"Sudden Doom","icon":"spell_shadow_painspike","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your main-hand autoattacks have a chance to make your next Death Coil cost no Runic Power."},"49206":{"name_enus":"Summon Gargoyle","icon":"ability_deathknight_summongargoyle","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"A Gargoyle flies into the area and bombards the target with Nature damage modified by the Death Knight's attack power.  Persists for 30 sec."},"11213":{"name_enus":"Arcane Concentration","icon":"spell_shadow_manaburn","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives you a 3% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by 100%."},"11255":{"name_enus":"Improved Counterspell","icon":"spell_frost_iceshock","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Counterspell also silences the target for 2 sec."},"44400":{"name_enus":"Netherwind Presence","icon":"ability_mage_netherwindpresence","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your spell haste by 1%."},"29447":{"name_enus":"Torment the Weak","icon":"spell_arcane_focusedpower","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Arcane damage spells deal 2% more damage to snared or slowed targets."},"84722":{"name_enus":"Invocation","icon":"spell_arcane_invocation","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You gain a 5% damage bonus for 8 sec after successfully interrupting a spell."},"83513":{"name_enus":"Improved Arcane Missiles","icon":"spell_nature_starfall","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the number of missiles fired by your Arcane Missiles spell by 1."},"31569":{"name_enus":"Improved Blink","icon":"spell_arcane_blink","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases your speed by 35% for 3 sec after casting the Blink spell."},"44378":{"name_enus":"Arcane Flows","icon":"ability_mage_potentspirit","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown of your Presence of Mind, Arcane Power and Invisibility spells by 12% and the cooldown of your Evocation spell by 1 min."},"12043":{"name_enus":"Presence of Mind","icon":"spell_nature_enchantarmor","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When activated, your next Mage spell with a casting time less than 10 sec becomes an instant cast spell.<!--cooldown:44378:1.76 min cooldown--><!--cooldown:44379:1.5 min cooldown-->"},"44404":{"name_enus":"Missile Barrage","icon":"ability_mage_missilebarrage","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Arcane Missiles spell will fire its missiles every 0.6 sec."},"31574":{"name_enus":"Prismatic Cloak","icon":"spell_arcane_prismaticcloak","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces all damage taken by 2% and reduces the fade time of your Invisibility spell by 1 sec."},"11210":{"name_enus":"Improved Polymorph","icon":"spell_nature_polymorph","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When a target you've polymorphed is damaged, that target is stunned for 1.5 sec.  This effect cannot occur more often than once every 10 sec."},"82930":{"name_enus":"Arcane Tactics","icon":"spell_arcane_arcanetactics","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases the damage of all party and raid members within 100 yards by 3%."},"44394":{"name_enus":"Incanter's Absorption","icon":"ability_mage_incantersabsorbtion","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"When your Mana Shield or Mage Ward absorbs damage your spell damage is increased by 10% of the amount absorbed for 10 sec.  In addition, when your Mana Shield is destroyed, all enemies within 6 yards are knocked back 12 yards."},"90724":{"name_enus":"","icon":"","screenshot":{},"displayName":"","skillcategory":0,"rank_enus":"","description_enus":""},"90787":{"name_enus":"Improved Arcane Explosion","icon":"spell_nature_wispsplode","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the global cooldown of your Arcane Explosion spell by 0.3 sec, reduces the threat generated by 40%, and reduces the mana cost by 25%."},"31571":{"name_enus":"Arcane Potency","icon":"spell_arcane_arcanepotency","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance of your next two damaging spells by 7% after gaining Clearcasting or Presence of Mind."},"31589":{"name_enus":"Slow","icon":"spell_nature_slow","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Reduces target's movement speed by 60%, increases the time between ranged attacks by 60% and increases casting time by 30%.  Lasts 15 sec.  Slow can only affect one target at a time."},"86181":{"name_enus":"Nether Vortex","icon":"spell_arcane_blast","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives your Arcane Blast spell a 50% chance to apply the Slow spell to any target it damages if no target is currently affected by Slow."},"54646":{"name_enus":"Focus Magic","icon":"spell_arcane_studentofmagic","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Increases the target's chance to critically hit with spells by 3% for 30 min.  When the target critically hits your chance to critically hit with spells is increased by 3% for 10 sec.  Cannot be cast on self.  Limit 1 target."},"31584":{"name_enus":"Improved Mana Gem","icon":"inv_misc_gem_emerald_01","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Mana gained from your Mana Gem also increases your spell power by 1% of your maximum mana for 15 sec."},"12042":{"name_enus":"Arcane Power","icon":"spell_nature_lightning","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When activated, you deal 20% more spell damage and damaging spells cost 10% <!--sp99064:0-->more<!--sp99064--> mana to cast. [<span class='q2'>Glyph of Arcane Power</span>: <span class='q9'>While Arcane Power is active, the global cooldown of your Blink, Mana Shield, and Mirror Image is reduced to zero</span>]This effect lasts 15 sec.<!--cooldown:44378:1.76 min cooldown--><!--cooldown:44379:1.5 min cooldown-->"},"83049":{"name_enus":"Early Frost","icon":"spell_frost_chillingbolt","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cast time of your Frostbolt spell by 0.3 secs.  This effect becomes inactive for 15 sec after use."},"11151":{"name_enus":"Piercing Ice","icon":"spell_frost_frostbolt","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance of your spells by 1%."},"11170":{"name_enus":"Shatter","icon":"spell_frost_frostshock","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Multiplies the critical strike chance of all your spells against frozen targets by 2, and increases the damage done by Frostbolt against frozen targets by 10%."},"31670":{"name_enus":"Ice Floes","icon":"spell_frost_icefloes","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the cooldown of your Frost Nova, Cone of Cold, Ice Block, Cold Snap, Ice Barrier, and Icy Veins spells by 7%."},"11190":{"name_enus":"Improved Cone of Cold","icon":"spell_frost_glacier","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Cone of Cold also freezes targets for 2 sec."},"83156":{"name_enus":"Piercing Chill","icon":"spell_frost_piercing-chill","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Frostbolt criticals apply the chill effect to 1 additional nearby targets."},"11175":{"name_enus":"Permafrost","icon":"spell_frost_wisp","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Chill effects reduce the target's speed by an additional 4%, and the target's healing received.  In addition, whenever you deal spell damage, your Water Elemental is healed for 5% of the amount dealt."},"11185":{"name_enus":"Ice Shards","icon":"spell_frost_ice-shards","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Adds a chill effect to your Blizzard spell.  This effect lowers the target's movement speed by 25%.  Lasts 2 sec.  In addition, increases the range of your Ice Lance spell by 2 yards."},"12472":{"name_enus":"Icy Veins","icon":"spell_frost_coldhearted","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Hastens your spellcasting, increasing spell casting speed by 20% and reduces the pushback suffered from damaging attacks while casting by 100%. [<span class='q2'>Glyph of Icy Veins</span>: <span class='q9'>Casting Icy Veins removes all movement slowing and cast time slowing effects</span>]  Lasts 20 sec.<!--cooldown:31670:2.79 min cooldown--><!--cooldown:31672:2.58 min cooldown--><!--cooldown:55094:2.4 min cooldown-->"},"44543":{"name_enus":"Fingers of Frost","icon":"ability_mage_wintersgrasp","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives your offensive Chill effects a 7% chance to grant you the Fingers of Frost effect, which causes your next Ice Lance or Deep Freeze spell to act as if your target were frozen and increases Ice Lance damage by 25%.  Fingers of Frost can accumulate up to 2 charges and lasts 15 sec."},"86259":{"name_enus":"Improved Freeze","icon":"spell_frost_summonwaterelemental","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives your Water Elemental's Freeze spell a 33% chance to grant 2 charges of Fingers of Frost when it strikes enemy targets."},"44561":{"name_enus":"Enduring Winter","icon":"spell_frost_arcticwinds","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the mana cost of all spells by 3%.  In addition, your Frostbolt spell has a 33% chance to grant up to 10 party or raid members mana regeneration equal to 1% of their maximum mana over 10 sec."},"11958":{"name_enus":"Cold Snap","icon":"spell_frost_wizardmark","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"When activated, this spell finishes the cooldown on all Frost spells you recently cast.<!--cooldown:31670:7.44 min cooldown--><!--cooldown:31672:6.88 min cooldown--><!--cooldown:55091:7.2 min cooldown--><!--cooldown:55092:6.4 min cooldown--><!--cooldown:55094:6.4 min cooldown-->"},"44546":{"name_enus":"Brain Freeze","icon":"ability_mage_brainfreeze","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your spells no longer trigger Arcane Missiles.  Instead, your Frost damage spells with chilling effects have a 5% chance to cause your next Fireball or Frostfire Bolt spell to be instant cast and cost no mana.  When Frostfire Bolt is instant, it can benefit from Fingers of Frost.  Brain Freeze cannot be triggered by Frostfire Bolt."},"44745":{"name_enus":"Shattered Barrier","icon":"ability_mage_coldasice","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives your Ice Barrier spell a 100% chance to freeze all enemies within 10 yds for 2 sec when it is destroyed."},"11426":{"name_enus":"Ice Barrier","icon":"spell_ice_lament","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Instantly shields you, absorbing <!--sp63095:0-->[(<!--pts1:1:0:11426-->8069<!----> + Spell power * 0.87)]<!--sp63095--> damage.  Lasts 1 min.  While the shield holds, spellcasting will not be delayed by damage.<!--cooldown:31670:27.9 sec cooldown--><!--cooldown:31672:25.8 sec cooldown--><!--cooldown:55091:27 sec cooldown--><!--cooldown:55092:24 sec cooldown--><!--cooldown:55094:24 sec cooldown-->"},"86303":{"name_enus":"Reactive Barrier","icon":"spell_frost_manarecharge","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives the caster a 50% chance for the Ice Barrier spell to automatically cast with no mana cost upon taking damage that lowers the caster's life below 50%.  This effect obeys Ice Barrier's cooldown, and will trigger the cooldown when activated."},"84726":{"name_enus":"Frostfire Orb","icon":"spell_firefrost-orb","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Converts your Flame Orb into a Frostfire Orb, causing your Frostfire Orb to benefit from your Frost Specialization.  In addition, reduces the speed of targets slowed by your Frostfire Bolt's chill effect by an additional 10%."},"44572":{"name_enus":"Deep Freeze","icon":"ability_mage_deepfreeze","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Stuns the target for 5 sec.  Only usable on Frozen targets.  Deals [<!--pts1:1:0:71757-->1037<!----> * (((<!--sp31676:0-->(<!--sp31675:0--><!--sp31674:0-->1<!--sp31674--><!--sp31675-->)<!--sp31676-->)) * <!--sp12953:0--> (<!--sp12952:0--><!--sp11151:0-->1<!--sp11151--><!--sp12952-->)<!--sp12953-->)] to [<!--pts1:2:0:71757-->1299<!----> * (((<!--sp31676:0-->(<!--sp31675:0--><!--sp31674:0-->1<!--sp31674--><!--sp31675-->)<!--sp31676-->)) * <!--sp12953:0--> (<!--sp12952:0--><!--sp11151:0-->1<!--sp11151--><!--sp12952-->)<!--sp12953-->)] damage to targets that are permanently immune to stuns."},"29074":{"name_enus":"Master of Elements","icon":"spell_fire_masterofelements","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your spell criticals will refund 15% of their base mana cost."},"11083":{"name_enus":"Burning Soul","icon":"spell_burningsoul","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the casting time lost from taking damaging attacks by 23%."},"11078":{"name_enus":"Improved Fire Blast","icon":"spell_fire_fireball","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the critical strike chance of your Fire Blast spell by 4% and increases its range by 5 yards."},"11119":{"name_enus":"Ignite","icon":"spell_fire_incinerate","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your critical strikes from non-periodic Fire damage spells cause the target to burn for an additional 13% of your spell's damage over 4 sec."},"18459":{"name_enus":"Fire Power","icon":"spell_fire_immolation","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases the damage of your Fire spells by 1% and gives your Flame Orb a 33% chance to explode for <!--pts1:0:0:83619-->1235.5<!----> damage at the end of its duration."},"31641":{"name_enus":"Blazing Speed","icon":"spell_fire_burningspeed","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives you a 5% chance when hit by a melee or ranged attack to increase your movement speed by 50% and dispel all effects that prevent movement.  This effect lasts 8 sec."},"11103":{"name_enus":"Impact","icon":"spell_fire_meteorstorm","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Gives your damaging spells a 5% chance to reset the cooldown on Fire Blast and to cause the next Fire Blast you cast to stun the target for 2 sec and spread any Fire damage over time effects to nearby enemy targets within 12 yards."},"86948":{"name_enus":"Cauterize","icon":"spell_fire_rune","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"You have a 50% chance that an attack which would otherwise kill you will instead bring you to 40% of your maximum health.  However, you will burn for 12% of your maximum health every 1.5 sec for the next 6 sec.  This effect cannot occur more than once per minute."},"11113":{"name_enus":"Blast Wave","icon":"spell_holy_excorcism_02","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"A wave of flame radiates outward from the target location, damaging all enemies caught within the blast for <!--pts1:0:0:11113-->852 to 1003<!----> Fire damage and are slowed by <!--pts2:0:0:11113-->70<!---->% for 3 sec."},"44445":{"name_enus":"Hot Streak","icon":"ability_mage_hotstreak","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your spells no longer trigger Arcane Missiles.  Instead, your critical strikes with Fireball, Frostfire Bolt, Scorch, Pyroblast, or Fire Blast have a chance to cause your next Pyroblast spell cast within 15 sec to be instant cast and cost no mana."},"11115":{"name_enus":"Improved Scorch","icon":"spell_fire_soulburn","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the mana cost of your Scorch spell by 50%."},"11094":{"name_enus":"Molten Shields","icon":"spell_fire_firearmor","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the global cooldown of your Mage Ward spell by 1 sec and your Blazing Speed also removes any movement slowing effects when triggered and is also triggered any time Mage Ward dissipates from absorbing damage."},"11129":{"name_enus":"Combustion","icon":"spell_fire_sealoffire","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Combines your damaging periodic Fire effects on an enemy target but does not consume them, instantly dealing <!--pts2:0:0:11129-->955 to 1131<!----> Fire damage and creating a new periodic effect that lasts 10 sec and deals damage per time equal to the sum of the combined effects."},"44446":{"name_enus":"Improved Hot Streak","icon":"ability_mage_hotstreak","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Any time you score 2 non-periodic critical strikes in a row with your Fireball, Frostfire Bolt, Scorch, Pyroblast, or Fire Blast spells, you have a 50% chance to trigger your Hot Streak effect."},"86914":{"name_enus":"Firestarter","icon":"ability_mage_firestarter","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Allows you to cast the Scorch spell while moving."},"84673":{"name_enus":"Improved Flamestrike","icon":"spell_fire_selfdestruct","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Reduces the casting time of your Flamestrike spell by 50% and gives you a 50% chance that your Blast Wave spell will also automatically Flamestrike the same location if two or more targets are affected by the Blast Wave."},"31661":{"name_enus":"Dragon's Breath","icon":"inv_misc_head_dragon_01","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"Targets in a cone in front of the caster take <!--pts1:0:0:31661-->1195 to 1388<!----> Fire damage and are disoriented for 5 sec.  Any direct damaging attack will revive targets."},"31679":{"name_enus":"Molten Fury","icon":"spell_fire_moltenblood","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases damage of all spells against targets with less than 35% health by 4%."},"34293":{"name_enus":"Pyromaniac","icon":"spell_fire_burnout","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Increases spell haste by 5% if 3 or more targets are taking Fire damage over time from your spells."},"11095":{"name_enus":"Critical Mass","icon":"spell_nature_wispheal","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"Rank 1","description_enus":"Your Living Bomb and Flame Orb spells deal 5% more damage, and your Pyroblast and Scorch spells have a 33% chance to cause your target to be vulnerable to spell damage, increasing spell critical strike chance against that target by 5% and lasts 30 sec."},"44457":{"name_enus":"Living Bomb","icon":"ability_mage_livingbomb","screenshot":{},"displayName":"","skillcategory":-2,"rank_enus":"","description_enus":"The target becomes a Living Bomb, taking <!--pts1:3:4:44457-->840<!----> Fire damage over 12 sec.  After 12 sec, the target explodes dealing <!--pts1:0:0:44461-->420<!----> Fire damage to up to 3 enemies within 10 yards.  Limit 3 targets."}});
